<script setup>
import { computed, ref } from 'vue'
import { useSchoolStore } from '../stores/school'
const school = useSchoolStore()
const classFilter = ref('All classes')
const selectedDate = ref(new Date().toISOString().slice(0, 10))
const rows = computed(() => school.attendance.filter(student => classFilter.value === 'All classes' || student.className === classFilter.value))
const presentCount = computed(() => rows.value.filter(student => student.status === 'Present').length)
const rate = computed(() => rows.value.length ? Math.round(presentCount.value / rows.value.length * 100) : 0)
function markAll(status) { for (const student of rows.value) school.setAttendance(student.id, status) }
</script>
<template><div class="page-intro"><div><div class="date-label">DAILY CLASS RECORD</div><h1>Attendance <span class="live-dot"></span></h1><p>Keep your class records accurate and up to date.</p></div><div class="attendance-intro-actions"><input class="date-input" type="date" v-model="selectedDate"/><button class="primary-button" @click="markAll('Present')">✓ Save attendance</button></div></div><div class="attendance-stats"><div class="mini-stat"><span class="mini-icon icon-mint">✓</span><div><small>Present today</small><strong>{{ presentCount }} <i>students</i></strong></div><span class="mini-rate">{{ rate }}%</span></div><div class="mini-stat"><span class="mini-icon icon-peach">×</span><div><small>Absent today</small><strong>{{ rows.length - presentCount }} <i>students</i></strong></div><span class="mini-rate absent-rate">{{ 100-rate }}%</span></div><div class="mini-stat"><span class="mini-icon icon-lavender">♙</span><div><small>Total students</small><strong>{{ rows.length }} <i>in class</i></strong></div></div></div><section class="panel attendance-register"><div class="directory-toolbar"><div><h2>Class register</h2><p>{{ new Date(`${selectedDate}T12:00:00`).toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }) }}</p></div><div class="table-tools"><select v-model="classFilter" class="select-pill" aria-label="Filter by class"><option>All classes</option><option>Grade 7</option><option>Grade 8</option></select><button class="outline-button" @click="markAll('Present')">Mark all present</button></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>STUDENT</th><th>CLASS & SECTION</th><th>STUDENT ID</th><th>ATTENDANCE STATUS</th></tr></thead><tbody><tr v-for="student in rows" :key="student.id"><td><div class="person-cell"><span class="avatar" :class="`avatar-${student.color || 'lavender'}`">{{ student.initials }}</span><span><strong>{{ student.name }}</strong><small>{{ student.email || 'Student account' }}</small></span></div></td><td>{{ student.className }} · {{ student.section }}</td><td>{{ student.id }}</td><td><div class="attendance-toggle"><button :class="{ chosen: student.status === 'Present', present: student.status === 'Present' }" @click="school.setAttendance(student.id, 'Present')"><i>✓</i> Present</button><button :class="{ chosen: student.status === 'Absent', absent: student.status === 'Absent' }" @click="school.setAttendance(student.id, 'Absent')"><i>×</i> Absent</button></div></td></tr></tbody></table></div><div class="register-note"><span>ℹ</span> Attendance records are saved in this browser for demonstration purposes.</div></section></template>
